from openai import OpenAI

client = OpenAI()
SPEND = {"input_tokens": 0, "output_tokens": 0}


def ask(messages):
    """Stream an answer and meter what it cost."""
    stream = client.chat.completions.create(
        model="gpt-4o",
        messages=messages,
        stream=True,
        stream_options={"include_usage": True},
    )
    text = ""
    saw_usage = False
    for chunk in stream:
        if chunk.usage is not None:
            saw_usage = True
            SPEND["input_tokens"] += chunk.usage.prompt_tokens
            SPEND["output_tokens"] += chunk.usage.completion_tokens
        if chunk.choices and chunk.choices[0].delta.content:
            text += chunk.choices[0].delta.content
    if not saw_usage:
        raise RuntimeError("stream ended with no usage chunk: spend is unmetered")
    return text


def budget_left(ceiling):
    return ceiling - (SPEND["input_tokens"] + SPEND["output_tokens"])
